// The URL identifies the website and section; the overview stays compact.
let selectedDomain=null,selectedTab='growth',goalRows=[],goalsReady=false,goalStatus='';const healthChecks=new Map(),mobileChecks=new Map();
const tabs=[['growth','Growth'],['business','Business results'],['followup','Follow-up'],['health','Website health'],['goals','Goals'],['changes','Changes']];
const metricLabels={sessions:'Website sessions',impressions:'Search impressions',clicks:'Search clicks',forms:'Accepted form events',inquiries:'CRM inquiries created',confirmed:'Bookings from inquiries',completedTours:'Completed tours'};
const micro=document.createElement('section');micro.id='micro';micro.hidden=true;document.querySelector('.foot').before(micro);
const macroSections=[...document.querySelectorAll('main>section')].filter(x=>x!==micro);const macroTitle=document.querySelector('.header h1'),macroDescription=document.querySelector('.header p'),macroEyebrow=document.querySelector('.header .eyebrow');
function siteUrl(domain,tab='growth'){const p=new URLSearchParams();if(domain){p.set('site',domain);p.set('tab',tab)}p.set('days',document.getElementById('days').value);if(domain&&document.getElementById('comparison').value==='year')p.set('compare','year');if(document.getElementById('include-tests').checked)p.set('tests','include');return '/portfolio/?'+p;}
function siteLogoNav(s){return `<nav class="site-logos" aria-label="Portfolio websites">${sites.map(x=>`<a data-route href="${siteUrl(x.domain,selectedTab)}" aria-label="${escape(x.name)} reporting" title="${escape(x.name)}" ${x.domain===s.domain?'aria-current="page"':''}><img src="brands/${x.domain}.${x.domain==='eyesondanang.com'?'webp':'png'}" alt="" width="58" height="58"></a>`).join('')}</nav>`;}
function followupPanel(s){if(s.domain!==sites[0].domain)return '<h2>Inquiry follow-up</h2><p class="muted">CRM follow-up reporting is not connected for this website. Accepted form events are available in Business results; they do not establish whether a person was contacted.</p>';const f=payload?.business?.followup;if(f?.status!=='connected')return '<h2>Mindo · inquiry follow-up</h2><p class="muted">Follow-up reporting is unavailable. Open the Guest CRM to review records.</p><p><a href="/guest-crm/">Open Guest CRM →</a></p>';const c=f.counts;const items=[['contact','New inquiries awaiting contact','New for at least two calendar days with no usable contact date.'],['prospectOverdue','Overdue prospect follow-ups','Open prospects whose follow-up date is before the review day.'],['guestOverdue','Overdue booked-guest follow-ups','Booked guests with an overdue follow-up date.'],['quotes','Quotes awaiting a response','Open quotes at least seven days old with no newer recorded contact.'],['payment','Payment status needs review','Explicit pending or unpaid statuses; this is not a dollar balance.'],['unscheduled','Prospects without a follow-up date','Open prospects with no usable next follow-up date.']];return `<div class="panelhead"><div><h2>Mindo · inquiry follow-up</h2><p class="muted">Inquiries created ${escape(f.start)} → ${escape(f.end)} · reviewed as of ${escape(f.asOf)}</p></div><a href="/guest-crm/">Guest CRM ↗</a></div><div class="queuegrid">${items.map(([key,label,meaning])=>{const p=new URLSearchParams({review:key,start:f.start,end:f.end,asOf:f.asOf});return `<a class="queuecard" href="/guest-crm/?${p}"><span class="eyebrow">${label}</span><strong>${number(c[key])}</strong><small>${meaning}</small><span>Review records →</span></a>`}).join('')}</div><p class="muted">${number(c.cohort)} eligible CRM records were created in this window, including closed or cancelled records. This broader review cohort can differ from the active-inquiry business count. Queues can overlap. These are current CRM statuses for the selected inquiry cohort, not the number of messages sent during the period.</p><div class="detailgrid"><article><h3>Recorded first-response time</h3><strong>${c.responseRecorded? (c.responseHoursTotal/c.responseRecorded).toFixed(1)+' hours':'—'}</strong><p class="muted">${number(c.responseRecorded)} inquiries have valid first-response timestamps; ${number(c.responseMissing)} lack them. Last-contact timestamps are not used as first response. This average may not represent all inquiries.</p></article><article><h3>CRM date completeness</h3><strong>${number(c.missingDate)}</strong><p class="muted">Records across CRM history lack usable creation dates and cannot be assigned to this period. Review <a href="/guest-crm/?${new URLSearchParams({review:'missingDate',start:f.start,end:f.end,asOf:f.asOf})}">missing dates →</a>.</p></article></div>`;}
function businessPanel(s){if(s.domain===sites[0].domain)return document.getElementById('business').innerHTML+`<div class="detailgrid"><article><h3>Earned revenue & profit</h3><strong>Reconciliation pending</strong><p class="muted">Completed-tour counts are connected. Reconciled financial amounts for this reporting period are not connected yet.</p><a href="/reports/?report=kpis">Open existing financial reports ↗</a></article><article><h3>Payments received</h3><strong>Not connected</strong><p class="muted">Cash receipt dates and tour completion dates measure different things. Deposits and later payments must be reconciled before showing earned revenue or margins here.</p></article></div>`+inquiryPanel(s);return `<h2>${escape(s.name)} · business results</h2><div class="detailstats"><div><span class="eyebrow">Accepted form events</span><strong>${number(forms(s))}</strong><small>Events · not unique inquiries</small></div><div><span class="eyebrow">Revenue</span><strong>—</strong><small>Financial reporting not connected</small></div><div><span class="eyebrow">Bookings / appointments</span><strong>—</strong><small>CRM reporting not connected</small></div><div><span class="eyebrow">Tracking</span><strong style="font-size:16px">${escape(trackingStatus(s).label)}</strong></div></div>${inquiryPanel(s)}<p class="muted">${s.domain==='arguellodentistry.com'?'Only aggregate website interactions are shown. Patient details are excluded.':'Business outcomes remain separate from website interactions.'}</p>`;}
function healthPanel(s){const h=healthChecks.get(s.domain),m=mobileChecks.get(s.domain);return `<h2>Website health</h2><p class="muted">Run checks when reviewing a website. No background polling or paid monitoring service.</p><div class="detailgrid"><article><h3>Important public pages</h3><button data-health="pages" ${h?.loading?'disabled':''}>${h?.loading?'Checking pages…':'Check page availability'}</button>${h?.error?`<p role="alert">${escape(h.error)}</p>`:''}${h?.pages?smallTable(['Page','HTTP result','Response time'],h.pages.map(r=>`<tr><td class="wraptext">${escape(r.url)}</td><td>${r.reachable===null?'Unknown':r.reachable?'Reachable':'Needs review'} ${r.status?'· '+r.status:''}</td><td>${r.elapsedMs==null?'—':number(r.elapsedMs)+' ms'}</td></tr>`))+`<p class="muted">Checked ${escape(new Date(h.checkedAt).toLocaleString())}.</p>`:''}<p class="muted">Homepage and up to two leading search pages. Server response time is not page-load speed. A reachable page does not prove its inquiry form delivers messages.</p></article><article><h3>Mobile performance</h3><button data-health="mobile" ${m?.loading?'disabled':''}>${m?.loading?'Running Google audit…':'Run mobile audit'}</button> <a href="https://pagespeed.web.dev/analysis?url=${encodeURIComponent('https://'+s.domain+'/')}&form_factor=mobile" target="_blank" rel="noopener">PageSpeed report ↗</a>${m?.error?`<p role="alert">${escape(m.error)}</p>`:''}${m?.mobile?`<div class="detailstats"><div><span class="eyebrow">Performance score</span><strong>${number(m.mobile.score)} / 100</strong></div><div><span class="eyebrow">LCP · lab</span><strong>${m.mobile.lcpMs==null?'—':(m.mobile.lcpMs/1000).toFixed(1)+' s'}</strong></div><div><span class="eyebrow">CLS · lab</span><strong>${m.mobile.cls==null?'—':m.mobile.cls.toFixed(3)}</strong></div><div><span class="eyebrow">Blocking · lab</span><strong>${number(m.mobile.blockingMs)} ms</strong></div></div><p class="muted">Audit ${escape(new Date(m.checkedAt).toLocaleString())}. Field experience: ${escape(m.mobile.fieldCategory||'unavailable or insufficient traffic')}.</p>`:''}<p class="muted">Google’s simulated mobile audit for the homepage. Lab results vary between runs and do not establish a real-user Core Web Vitals pass. If the free API is quota limited, open the PageSpeed report directly.</p></article></div>${inspectionPanel(s)}<details class="subdetail"><summary>Inquiry delivery status</summary><p>Accepted-submission handling is verified in the website code. End-to-end delivery is not tested by these page checks. No customer or patient forms are submitted.</p>${inquiryPanel(s)}</details>`;}
function goalValue(s,g){if(!payload||Number(document.getElementById('days').value)!==g.days)return null;if(['inquiries','confirmed','completedTours'].includes(g.metric))return payload.business?.status==='connected'?payload.business[g.metric]:null;return g.metric==='forms'?forms(s):s[g.metric]??null;}
function goalsPanel(s){const g=goalRows.find(x=>x.domain===s.domain),value=g?goalValue(s,g):null,allowed=['sessions','impressions','clicks','forms',...(s.domain===sites[0].domain?['inquiries','confirmed','completedTours']:[])];return `<h2>${escape(s.name)} · goal</h2><p class="muted">${s.stage==='Earning'?'Prioritize inquiries, bookings or completed tours.':s.domain==='arguellodentistry.com'?'Prioritize accepted appointment/contact events while CRM reporting is being connected.':'Prioritize search impressions and clicks while the website is developing.'} Set one primary target per website.</p>${!goalsReady?'<p class="muted">Shared goals are loading or unavailable.</p>':g?`<article class="goalcard"><span class="eyebrow">${metricLabels[g.metric]} · rolling ${g.days} completed days</span><strong>${number(value)} / ${number(g.target)}</strong>${value!=null?`<progress max="${g.target}" value="${Math.min(value,g.target)}" aria-label="Goal progress"></progress><p>${(100*value/g.target).toFixed(0)}% of target${value>=g.target?' · target reached':''}</p><p class="muted">Measured ${escape(payload.start)} → ${escape(payload.end)}.</p>`:`<p class="muted">${Number(document.getElementById('days').value)!==g.days?'Select '+g.days+' days to measure this target on the correct window.':'The reporting source is unavailable.'}</p>`}<p class="muted">Saved ${escape(new Date(g.updated_at).toLocaleDateString())}. This is a rolling-window target, not a calendar-month total.</p></article>`:'<p class="muted">No target set. Targets are not generated automatically.</p>'}<form id="goal-form" class="logform"><label>Primary metric<select name="metric">${allowed.map(k=>`<option value="${k}" ${g?.metric===k?'selected':''}>${metricLabels[k]}</option>`).join('')}</select></label><label>Reporting window<select name="days">${[7,28,90].map(d=>`<option value="${d}" ${(g?.days||28)===d?'selected':''}>${d} completed days</option>`).join('')}</select></label><label>Target<input name="target" type="number" min="1" max="100000000" step="1" required value="${g?.target||''}"></label><button ${!goalsReady?'disabled':''}>Save target</button>${g?'<button type="button" data-clear-goal>Remove target</button>':''}</form><p id="goal-status" role="status" class="muted">${escape(goalStatus||'Saved privately in the existing shared admin database.')}</p>`;}
function paintMicro(){const booked=document.getElementById('macro-bookings');booked.textContent=number(payload?.business?.status==='connected'?payload.business.confirmed:null);const overview=document.querySelector('.navlinks .current');overview.href=siteUrl(null);overview.dataset.route='';const s=sites.find(x=>x.domain===selectedDomain),active=!!s;macroSections.forEach(x=>x.hidden=active||(x.id==='business'));micro.hidden=!active;document.getElementById('comparison-label').hidden=!active;macroTitle.textContent=active?s.name:'Website growth';macroEyebrow.textContent=active?'Portfolio / website detail':'Nine projects · one overview';macroDescription.textContent=active?s.domain:'Traffic and Google search visibility across your portfolio.';document.title=active?s.name+' | Portfolio Admin':'Portfolio | Admin overview';if(!active)return;const open=[...micro.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);const content=selectedTab==='growth'?previousDetail(s)+(typeof trackingPanel==='function'?trackingPanel(s):''):selectedTab==='business'?businessPanel(s):selectedTab==='followup'?followupPanel(s):selectedTab==='health'?healthPanel(s):selectedTab==='goals'?goalsPanel(s):`<h2>Website changes</h2>${timeline(s.domain)}<p class="muted">Changes add context to the charts; timing does not establish causation.</p><a href="${siteUrl(null)}#change-form">Record a change in the portfolio timeline →</a>`;micro.innerHTML=`<div class="microbar"><a data-route href="${siteUrl(null)}">← All websites</a><a href="https://${s.domain}/" target="_blank" rel="noopener">Open website ↗</a></div>${siteLogoNav(s)}<nav class="microtabs" aria-label="Website detail sections">${tabs.map(([key,label])=>`<a data-route href="${siteUrl(s.domain,key)}" ${selectedTab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><section class="stats microstats" aria-label="Website totals">${[['Website sessions',s.sessions,s.priorSessions],['Search impressions',s.impressions,s.priorSearch?.impressions],['Search clicks',s.clicks,s.priorSearch?.clicks],['Accepted form events',forms(s),s.events==null?null:s.events.filter(e=>(Array.isArray(formEvents[s.domain])?formEvents[s.domain]:[formEvents[s.domain]]).includes(e.name)).reduce((n,e)=>n+(e.priorCount||0),0)]].map(([label,v,prior])=>`<article class="panel stat"><div class="eyebrow">${label}</div><strong>${number(v)}</strong>${delta(change(v,prior))}<small>${v!=null&&prior!=null?signed(v-prior)+' vs '+comparisonLabel():'No recorded comparison'}</small><small>${payload?escape(payload.start+' → '+payload.end):'Waiting for reporting data'}</small></article>`).join('')}</section><section class="panel tablepanel microcontent">${document.getElementById('comparison').value==='year'?'<p class="comparison-note">Comparing with the same calendar dates last year. Zero or missing recorded history does not establish a valid baseline; percentage change is withheld for a zero baseline.</p>':''}${typeof siteUpgrades==='function'?siteUpgrades(s):''}${content}</section>`;for(const d of micro.querySelectorAll('details'))if(open.includes(d.querySelector('summary')?.textContent))d.open=true;if(payload&&selectedTab==='growth'&&!['ready','loading','error'].includes(detailState.get(s.domain)))loadDetail(sites.indexOf(s));}
const macroRender=render;render=()=>{macroRender();rows.querySelectorAll('.details').forEach(r=>r.remove());for(const name of rows.querySelectorAll('.name')){const rowSite=sites.find(s=>name.textContent.includes(s.domain));if(rowSite)name.innerHTML=`<a data-route href="${siteUrl(rowSite.domain)}" style="text-decoration:none">${escape(rowSite.name)}<span class="domain">${escape(rowSite.domain)}</span></a>`;}for(const row of rows.querySelectorAll('tr')){const s=sites.find(s=>row.textContent.includes(s.domain)),g=goalRows.find(g=>g.domain===s?.domain);if(s&&g){const v=goalValue(s,g),label=v==null?'Target · '+g.days+' days':'Target · '+Math.round(v/g.target*100)+'%';row.children[1].insertAdjacentHTML('beforeend',`<span class="domain" title="${metricLabels[g.metric]}: ${g.target} in ${g.days} completed days">${escape(label)}</span>`);}}for(const b of rows.querySelectorAll('button[data-site]')){const s=sites[Number(b.dataset.site)],a=document.createElement('a');a.href=siteUrl(s.domain);a.dataset.route='';a.className='detailbtn';a.setAttribute('aria-label','Explore '+s.name);a.textContent='→';b.replaceWith(a);}for(const b of document.querySelectorAll('[data-review-site]')){const a=document.createElement('a');a.href=siteUrl(sites[Number(b.dataset.reviewSite)].domain);a.dataset.route='';a.className='rowlink';a.textContent='Review website →';b.replaceWith(a);}paintMicro();};
function readRoute(){const p=new URLSearchParams(location.search);selectedDomain=sites.some(s=>s.domain===p.get('site'))?p.get('site'):null;selectedTab=tabs.some(t=>t[0]===p.get('tab'))?p.get('tab'):'growth';const days=p.get('days');if(['7','28','90'].includes(days))document.getElementById('days').value=days;document.getElementById('comparison').value=selectedDomain&&p.get('compare')==='year'?'year':'previous';document.getElementById('include-tests').checked=p.get('tests')==='include';}
function navigate(url){const oldDays=document.getElementById('days').value,oldCompare=document.getElementById('comparison').value,oldTests=document.getElementById('include-tests').checked;history.pushState({},'',url);readRoute();render();if(oldDays!==document.getElementById('days').value||oldCompare!==document.getElementById('comparison').value||oldTests!==document.getElementById('include-tests').checked)load();window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();navigate(a.href);}},true);document.addEventListener('change',e=>{if(e.target.id==='site-picker')navigate(siteUrl(e.target.value,selectedTab));});window.addEventListener('popstate',()=>{const old=[document.getElementById('days').value,document.getElementById('comparison').value,document.getElementById('include-tests').checked].join();readRoute();render();if(old!==[document.getElementById('days').value,document.getElementById('comparison').value,document.getElementById('include-tests').checked].join())load();});
for(const id of ['days','include-tests','comparison'])document.getElementById(id).addEventListener('change',()=>{history.replaceState({},'',siteUrl(selectedDomain,selectedTab));if(id==='comparison')load();});
async function loadGoals(){try{const r=await fetch('/api/portfolio-goals',{cache:'no-store'}),p=await r.json();if(!r.ok||!p.ok)throw Error(p.error||'Goals unavailable.');goalRows=p.goals;goalsReady=true;}catch(e){goalStatus=e.message;goalsReady=false;}render();}
async function saveGoal(method,body){const domain=selectedDomain;try{const r=await fetch('/api/portfolio-goals'+(method==='DELETE'?'?site='+encodeURIComponent(domain):''),{method,headers:{'Content-Type':'application/json'},body:method==='POST'?JSON.stringify(body):undefined}),p=await r.json();if(!r.ok||!p.ok)throw Error(p.error||'Could not save target.');goalRows=p.goals;goalsReady=true;goalStatus=method==='DELETE'?'Target removed.':'Target saved to shared admin storage.';}catch(e){goalStatus=e.message;}render();}
micro.addEventListener('submit',e=>{if(e.target.id!=='goal-form')return;e.preventDefault();const data=new FormData(e.target);e.target.querySelector('button').disabled=true;saveGoal('POST',{domain:selectedDomain,metric:data.get('metric'),days:Number(data.get('days')),target:Number(data.get('target'))});});
micro.addEventListener('click',async e=>{if(e.target.closest('[data-clear-goal]'))return saveGoal('DELETE');const inspect=e.target.closest('[data-inspect]');if(inspect)return inspectSite(Number(inspect.dataset.inspect));const b=e.target.closest('[data-health]');if(!b)return;const domain=selectedDomain,s=sites.find(s=>s.domain===domain),mobile=b.dataset.health==='mobile',store=mobile?mobileChecks:healthChecks;if(store.get(domain)?.loading)return;store.set(domain,{loading:true});render();try{const pages=(s.searchPages||[]).map(p=>p.url).filter(v=>{try{const u=new URL(v);return u.protocol==='https:'&&[domain,'www.'+domain].includes(u.hostname)&&u.pathname!=='/'&&!u.search&&!u.hash;}catch{return false;}}).slice(0,2);const r=await fetch('/api/portfolio-health?site='+encodeURIComponent(domain)+(mobile?'&mobile=1':'&pages='+encodeURIComponent(JSON.stringify(pages))),{cache:'no-store'}),p=await r.json();if(!r.ok||!p.ok||p.domain!==domain)throw Error(p.error||'Health check unavailable.');store.set(domain,p);}catch(e){store.set(domain,{error:e.message});}render();});
readRoute();render();load();loadGoals();
